Object.assign(labels,BubsVendorContract.labels);
let vendorContext={category:'Photographer',focus:[],section:'Your profile'};
function vendorGreeting(){const key=vendorContext.focus[0],label=BubsVendorContract.labels[key];return 'Greet the wedding-business owner briefly. Help them complete their own profile. '+(label?'Ask one focused question about '+label+'. Use their existing draft as context; do not repeat facts already provided.':'Ask which business detail they would like to add or correct.')+' Explain that suggestions await their Apply action.'}
voiceScreen=function(){const focus=vendorContext.focus.length?vendorContext.focus:['name','email','price','delivery'],ready=!!voice.token,active=voice.run,connecting=voice.status==='Connecting gateway…';return heading('Let’s finish your profile.','Tell us what’s missing or what needs correcting. You review every suggested change.')+`<div class="voice-layout"><section class="card voice-conversation"><div class="card-head"><div><span class="eyebrow">YOUR ONBOARDING ASSISTANT</span><h2 style="margin-top:10px">A little help, in your own words.</h2></div><span class="assistant-status">${active?.ready?'Connected':active?'Starting your conversation…':ready?'Ready when you are':connecting?'Getting ready…':'Connection needed'}</span></div><div class="assistant-priorities"><b>Working on ${esc(vendorContext.section.toLowerCase())}</b><ul>${focus.slice(0,3).map(key=>`<li>${esc(BubsVendorContract.labels[key]||key)}</li>`).join('')}</ul><span>Correct any existing detail, or answer a missing one. The current draft is already here.</span></div>${voice.error?`<div class="assistant-error" role="status">${esc(!ready?"The assistant cannot reach its local service. Open the local experience on this computer, or restart the voice launcher.":voice.error)}${!ready?' <a href="http://127.0.0.1:4180/?v=12#setup" target="_blank" rel="noopener">Open the local experience ↗</a>':''}</div>`:''}<div class="voice-controls">${!active?`<button class="primary" id="voice-start" ${!ready?'disabled':''}>Start conversation</button><button class="secondary" id="voice-typed" ${!ready?'disabled':''}>Type instead · no microphone</button>`:`<button class="secondary" id="voice-mute" ${!active.ready||active.test||active.typed?'disabled':''}>${active.muted?'Unmute microphone':'Mute microphone'}</button><button class="primary" id="voice-stop">End conversation</button><span class="voice-clock" id="voice-clock">${voiceTimeRemaining()}</span>`}${!active&&!ready&&!connecting?'<button class="secondary" id="assistant-retry">Try connecting again</button>':''}</div><p class="voice-disclosure">You’ll hear AI-generated speech. Your conversation is sent to OpenAI. Microphone access begins only when you choose Start conversation. Sessions end after two minutes; use End conversation when finished.</p><h3 style="margin-top:24px">Your conversation</h3><div id="voice-captions" class="voice-captions" role="log" aria-live="polite">${voiceCaptions()}</div><label for="voice-note">Add an answer or correction</label><textarea id="voice-note" maxlength="2500" placeholder="For example: Our current starting price is $4,650 per wedding." ${!active?.ready?'disabled':''}></textarea><button class="secondary" id="voice-note-send" ${!active?.ready||voice.analysisBusy?'disabled':''}>${voice.analysisBusy?'Preparing suggestions…':'Suggest updates →'}</button><p class="small" style="margin-top:12px">${voice.analysisBusy?'Checking your answer…':`${Math.max(0,3-voice.analyses)} analysis round${voice.analyses===2?'':'s'} left this session. No automatic changes.`}</p><details class="assistant-setup-details"><summary>Session details & exports</summary><p>Two-minute sessions · 30-second idle cutoff · 10 starts/day · 3 analyses/session. Muting does not end billing. The local service keeps your API key off the website.</p><p>${voice.config?`${voice.config.startsToday}/10 starts used today.`:'The local service must be running on this computer.'}</p><button class="text-btn" id="voice-export-captions" ${voice.segments.length?'':'disabled'}>Export conversation ↓</button><button class="text-btn" id="voice-export-profile">Export working draft ↓</button></details>${active?'<button id="voice-start" hidden disabled>Start</button><button id="voice-typed" hidden disabled>Type</button>':''}<button id="voice-connect" hidden>Connect</button><button id="voice-test" hidden>Test</button><button id="voice-current" hidden>Current draft</button><button id="voice-sample" hidden>Sample</button></section><section class="card voice-draft"><span class="eyebrow">REVIEW BEFORE APPLYING</span><h2 style="margin-top:12px">Your proposed updates.</h2><p class="small">Each suggestion includes your exact words. Apply the changes you want to keep; they return to your profile immediately.</p><div id="voice-proposals">${voiceProposals()}</div>${voice.questions.length?`<h3 style="margin-top:24px">What we still need</h3><ul>${voice.questions.map(question=>`<li>${esc(question)}</li>`).join('')}</ul>`:''}<details style="margin-top:25px"><summary>Relevant details in your draft</summary><div class="assistant-focused-fields">${focus.map(key=>`<div><label>${esc(BubsVendorContract.labels[key]||key)}</label><p>${esc(voice.draft[key]||'Not provided yet')}</p></div>`).join('')}</div></details></section></div>`};
const vendorAssistantBind=bind;bind=function(){vendorAssistantBind();if(state.page!=='voice')return;if(document.getElementById('assistant-retry'))document.getElementById('assistant-retry').onclick=connectVoiceGateway;document.querySelectorAll('[data-voice-apply]').forEach(button=>{const previous=button.onclick;button.onclick=()=>{previous();sendVendorDraft();const applied=new Set(voice.proposals.filter(item=>item.applied).map(item=>item.field));vendorContext.focus=[...new Set([...vendorContext.focus.filter(key=>!applied.has(key)),...BubsVendorContract.keysForCategory(vendorContext.category).filter(key=>!voice.draft[key]?.trim())])].slice(0,8);if(voice.run?.ready)sendLive(voice.run,'session.thinking.append','The owner explicitly applied the suggested update. Current unanswered field identifiers: '+JSON.stringify(vendorContext.focus)+'. Current applied values (reference only): '+JSON.stringify(Object.fromEntries(voice.proposals.filter(item=>item.applied).map(item=>[item.field,voice.draft[item.field]]))).slice(0,900));refreshVoice()}})};
